import { createServerClient } from "@supabase/ssr";
import type { CookieMethodsServer } from "@supabase/ssr";
import { createClient } from "@supabase/supabase-js";

import { env } from "@aevryn/env/server";

/**
 * Server-side Supabase client bound to request cookies (SSR).
 *
 * Pass the request's cookie methods so token refreshes are written back to
 * the response. `setAll` is optional when it can't be written from a page or
 * route — in that case the proxy must refresh sessions instead.
 */
export function createServerSupabase(cookies: CookieMethodsServer) {
	return createServerClient(
		env.NEXT_PUBLIC_SUPABASE_URL,
		env.NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY,
		{
			cookies,
		},
	);
}

/**
 * Service-role client. Server-only — Storage/admin/trigger work, never
 * exposed to the client. Bypasses RLS, so only use in trusted server paths.
 */
export function createAdminClient() {
	return createClient(env.NEXT_PUBLIC_SUPABASE_URL, env.SUPABASE_SERVICE_ROLE_KEY, {
		auth: {
			autoRefreshToken: false,
			persistSession: false,
		},
	});
}

export type { CookieMethodsServer };

import { createBrowserClient } from "@supabase/ssr";

import { env } from "@aevryn/env/web";

let browserClient: ReturnType<typeof createBrowserClient> | undefined;

/**
 * Singleton browser Supabase client. Use inside client components.
 */
export function getBrowserSupabase() {
	if (!browserClient) {
		browserClient = createBrowserClient(
			env.NEXT_PUBLIC_SUPABASE_URL,
			env.NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY,
		);
	}
	return browserClient;
}

import type { SupabaseClient } from "@supabase/supabase-js";

/** Current session user or null. */
export async function getCurrentUser(
	supabase: SupabaseClient,
): Promise<{ id: string; email?: string | null } | null> {
	const {
		data: { user },
	} = await supabase.auth.getUser();
	if (!user) return null;
	return { id: user.id, email: user.email };
}

/** Current session user, throwing if unauthenticated. Auth-error — caught by route handlers. */
export async function requireUser(supabase: SupabaseClient): Promise<{
	id: string;
	email?: string | null;
}> {
	const user = await getCurrentUser(supabase);
	if (!user) throw new Error("Unauthenticated");
	return user;
}

export { createServerSupabase, createAdminClient } from "./server";
export type { CookieMethodsServer } from "./server";
export { getBrowserSupabase } from "./client";
export { getCurrentUser, requireUser } from "./user";

