import { identifyUser } from "evlog/better-auth";

import { createServerSupabase, getCurrentUser } from "@aevryn/auth";
import type { CookieMethodsServer } from "@aevryn/auth";

import { useLogger } from "@/lib/evlog";

function cookieMethodsFromRequest(req: Request): CookieMethodsServer {
	const cookies = new Map<string, string>();
	const header = req.headers.get("cookie");
	if (header) {
		for (const part of header.split(";")) {
			const eq = part.indexOf("=");
			if (eq <= 0) continue;
			const name = part.slice(0, eq).trim();
			const value = decodeURIComponent(part.slice(eq + 1).trim());
			if (name) cookies.set(name, value);
		}
	}
	return {
		getAll() {
			return Array.from(cookies, ([name, value]) => ({ name, value }));
		},
		setAll() {
			// Read-only: token refresh is handled by the proxy.
		},
	};
}

/**
 * Best-effort user identity enrichment for evlog wide events.
 * Only reads the session cookie — refresh is left to the proxy.
 */
export async function identifyEvlogUser(req: Request) {
	const supabase = createServerSupabase(cookieMethodsFromRequest(req));
	const user = await getCurrentUser(supabase);
	if (!user) return;
	identifyUser(
		useLogger(),
		{ user: { id: user.id, email: user.email }, session: {} },
		{ maskEmail: true },
	);
}

import { NextResponse } from "next/server";

import { createServerSupabaseForNext } from "@/lib/supabase-server";

/**
 * OAuth callback — exchanges the provider code for a session (writes auth
 * cookies) and routes the user into the app.
 */
export async function GET(request: Request) {
	const { searchParams, origin } = new URL(request.url);
	const code = searchParams.get("code");
	const next = searchParams.get("next") ?? "/workspace";

	if (code) {
		const supabase = await createServerSupabaseForNext();
		const { error } = await supabase.auth.exchangeCodeForSession(code);
		if (!error) {
			return NextResponse.redirect(`${origin}${next}`);
		}
	}

	return NextResponse.redirect(`${origin}/login?error=unable-to-sign-in`);
}

import { createServerClient } from "@supabase/ssr";
import { NextResponse } from "next/server";
import type { NextRequest } from "next/server";
import { evlogMiddleware } from "evlog/next";

const evlog = evlogMiddleware();

function createSupabase(request: NextRequest, response: NextResponse) {
	return createServerClient(
		process.env.NEXT_PUBLIC_SUPABASE_URL!,
		process.env.NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY!,
		{
			cookies: {
				getAll() {
					return request.cookies.getAll();
				},
				setAll(cookiesToSet) {
					cookiesToSet.forEach(({ name, value }) =>
						request.cookies.set(name, value),
					);
					cookiesToSet.forEach(({ name, value, options }) =>
						response.cookies.set(name, value, options),
					);
				},
			},
		},
	);
}

function isPublicPath(pathname: string) {
	return (
		pathname === "/login" ||
		pathname.startsWith("/login/") ||
		pathname.startsWith("/auth/")
	);
}

export async function proxy(request: NextRequest) {
	let response = await evlog(request);

	const supabase = createSupabase(request, response);

	// Refresh the session token if it's close to expiry (writes cookies).
	const {
		data: { user },
	} = await supabase.auth.getUser();

	const { pathname } = request.nextUrl;

	// Unauthenticated page requests → login.
	if (!user && !isPublicPath(pathname)) {
		const url = request.nextUrl.clone();
		url.pathname = "/login";
		url.searchParams.set("next", pathname);
		return NextResponse.redirect(url);
	}

	// Authenticated users skip login/root and land in the app.
	if (user && (isPublicPath(pathname) || pathname === "/")) {
		const url = request.nextUrl.clone();
		url.pathname = "/workspace";
		url.search = "";
		return NextResponse.redirect(url);
	}

	return response;
}

export const config = {
	matcher: [
		"/((?!_next/static|_next/image|favicon.ico|.*\\.(?:svg|png|jpg|jpeg|gif|webp|ico)$).*)",
	],
};

