import "dotenv/config";
import crypto from "node:crypto";

const url = process.env.NEXT_PUBLIC_SUPABASE_URL;
const jwtSecret = process.env.SUPABASE_SERVICE_ROLE_KEY; // doubles as JWT secret (HS256)
const userId = "2b034975-eb88-448a-a59f-62c80f4e99b9";

function sign(header, payload) {
	const h = Buffer.from(JSON.stringify(header)).toString("base64url");
	const p = Buffer.from(JSON.stringify(payload)).toString("base64url");
	const data = `${h}.${p}`;
	const sig = crypto.createHmac("sha256", jwtSecret).update(data).digest("base64url");
	return `${data}.${sig}`;
}

function jwt(claims) {
	return sign({ alg: "HS256", typ: "JWT" }, {
		...claims,
		sub: userId,
		role: "authenticated",
		aud: "authenticated",
		iat: Math.floor(Date.now() / 1000),
		exp: Math.floor(Date.now() / 1000) + 3600,
	});
}

const token = jwt({});

