import "dotenv/config";
import crypto from "node:crypto";

const url = process.env.NEXT_PUBLIC_SUPABASE_URL;
const anonKey = process.env.NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY;
const jwtSecret = process.env.SUPABASE_SERVICE_ROLE_KEY;
const userId = "2b034975-eb88-448a-a59f-62c80f4e99b9";

function sign(header, payload) {
	const h = Buffer.from(JSON.stringify(header)).toString("base64url");
	const p = Buffer.from(JSON.stringify(payload)).toString("base64url");
	const data = `${h}.${p}`;
	const sig = crypto.createHmac("sha256", jwtSecret).update(data).digest("base64url");
	return `${data}.${sig}`;
}

const token = sign({ alg: "HS256", typ: "JWT" }, {
	sub: userId,
	role: "authenticated",
	aud: "authenticated",
	iat: Math.floor(Date.now() / 1000),
	exp: Math.floor(Date.now() / 1000) + 3600,
	email: "test@test.dev",
});

async function ask(path) {
	const res = await fetch(`${url}/rest/v1/${path}`, {
		headers: {
			Authorization: `Bearer ${token}`,
			apikey: anonKey,
			"Content-Type": "application/json",
		},
	});
	console.log(path, "->", res.status, "|", (await res.text()).slice(0, 500));
}

await ask("workspaces?select=id,name,is_default");
await ask("user_profiles?select=id,user_id,onboarded");
await ask("workspace_members?select=id,workspace_id,role");
await ask("groups?select=id,name,kind");

