async listActivitiesByRun(
		runId: string,
		limit = 200,
	): Promise<RunActivity[]> {
		return this.scope().query.runActivities.findMany({
			where: eq(runActivities.runId, runId),
			orderBy: [asc(runActivities.createdAt)],
			limit,
		});
	}

