import {
	db,
	ids,
	schedules,
	type Db,
	type Schedule,
} from "@aevryn/db";
import { and, asc, eq, isNull, lte } from "drizzle-orm";

export interface CreateScheduleInput {
	workspaceId: string;
	threadId: string;
	userId: string;
	cron?: string;
	intervalSeconds?: number;
	startAt?: Date;
	config?: Record<string, unknown>;
}

/**
 * Recurrence config, one per (workspace, thread) — the blessed home for the
 * `createSchedule` capability (`sched_` ULID, SCHEMA.md §18). Created by the
 * agent mid-run and fired by `schedule-tick` (thread/run trigger=schedule).
 */
export class ScheduleService {
	constructor(private readonly client: Db = db) {}

	private scope(): Db {
		return this.client;
	}

	/**
	 * Create or replace the thread's schedule. Unique (workspace, thread):
	 * re-calling createSchedule for the same thread updates the config and
	 * re-arms the timer instead of stacking duplicate schedules.
	 */
	async upsert(input: CreateScheduleInput): Promise<Schedule> {
		const now = new Date();
		const [row] = await this.scope()
			.insert(schedules)
			.values({
				id: ids.schedule(),
				workspaceId: input.workspaceId,
				threadId: input.threadId,
				userId: input.userId,
				cron: input.cron ?? null,
				intervalSeconds: input.intervalSeconds ?? null,
				nextRunAt: input.startAt ?? now,
				config: input.config ?? null,
				enabled: true,
				updatedAt: now,
			})
			.onConflictDoUpdate({
				target: [schedules.workspaceId, schedules.threadId],
				set: {
					userId: input.userId,
					cron: input.cron ?? null,
					intervalSeconds: input.intervalSeconds ?? null,
					nextRunAt: input.startAt ?? now,
					config: input.config ?? null,
					enabled: true,
					updatedAt: now,
				},
			})
			.returning();
		return row!;
	}

	async findById(id: string): Promise<Schedule | undefined> {
		return this.scope().query.schedules.findFirst({
			where: eq(schedules.id, id),
		});
	}

	async listByThread(threadId: string): Promise<Schedule[]> {
		return this.scope().query.schedules.findMany({
			where: eq(schedules.threadId, threadId),
			orderBy: [asc(schedules.createdAt)],
		});
	}

	async listByWorkspace(
		workspaceId: string,
		limit = 100,
	): Promise<Schedule[]> {
		return this.scope().query.schedules.findMany({
			where: and(
				eq(schedules.workspaceId, workspaceId),
				isNull(schedules.threadId),
			),
			orderBy: [asc(schedules.createdAt)],
			limit,
		});
	}

	/** Enabled schedules whose next fire time has arrived. */
	async listDue(now: Date): Promise<Schedule[]> {
		return this.scope().query.schedules.findMany({
			where: and(
				eq(schedules.enabled, true),
				lte(schedules.nextRunAt, now),
			),
		});
	}

	async setEnabled(id: string, enabled: boolean): Promise<Schedule | undefined> {
		const [row] = await this.scope()
			.update(schedules)
			.set({ enabled })
			.where(eq(schedules.id, id))
			.returning();
		return row;
	}

	async markRan(
		id: string,
		nextRunAt: Date,
		lastRunId: string,
	): Promise<Schedule | undefined> {
		const [row] = await this.scope()
			.update(schedules)
			.set({
				nextRunAt,
				lastRunId,
				lastRunAt: new Date(),
			})
			.where(eq(schedules.id, id))
			.returning();
		return row;
	}

	async delete(id: string): Promise<void> {
		await this.scope().delete(schedules).where(eq(schedules.id, id));
	}
}

import { createHash, randomBytes } from "node:crypto";
import { env } from "@aevryn/env/server";
import {
	db,
	ids,
	webhookHooks,
	type Db,
	type WebhookHook,
} from "@aevryn/db";
import { eq } from "drizzle-orm";
import { z } from "zod";

export const webhookFireSchema = z.unknown().refine((value) => value !== undefined, {
	message: "Request body must not be empty",
});

export interface MintWebhookInput {
	runId: string;
	workspaceId: string;
	threadId: string;
	userId: string;
	instruction: string;
	expiresInSeconds?: number;
	reason?: string;
}

export interface ConsumeWebhookInput {
	token: string;
	payload: unknown;
}

export interface ConsumeResult {
	ok: boolean;
	reason?: "not-found" | "expired" | "already-fired" | "unavailable";
	hook?: WebhookHook;
}

/**
 * Durable wait/resume tokens — the blessed home for the `wait` decision
 * (`whk_` ULID, SCHEMA.md §19). The plaintext token is handed to the user,
 * never persisted; only its SHA-256 hash is stored (unauthenticated route
 * auths through the token alone). One run may mint several hooks.
 */
export class WebhookHookService {
	constructor(private readonly client: Db = db) {}

	private scope(): Db {
		return this.client;
	}

	/**
	 * Mint a hook and flip the run to `waiting`. Returns the raw token + the
	 * public URL to hand back to the model, which the user POSTs to when the
	 * external event happens.
	 */
	async mint(input: MintWebhookInput): Promise<{ token: string; url: string }> {
		const token = randomBytes(24).toString("base64url");
		const tokenHash = createHash("sha256").update(token).digest("hex");
		const expiresAt = input.expiresInSeconds
			? new Date(Date.now() + input.expiresInSeconds * 1000)
			: new Date(Date.now() + 30 * 24 * 60 * 60 * 1000);
		await this.scope().insert(webhookHooks).values({
			id: ids.webhookHook(),
			runId: input.runId,
			workspaceId: input.workspaceId,
			threadId: input.threadId,
			userId: input.userId,
			tokenHash,
			status: "active",
			expiresAt,
		});
		return {
			token,
			url: `${env.WEBHOOK_BASE_URL}/api/v1/hooks/${token}`,
		};
	}

	/**
	 * Consume a webhook by its plaintext token. Marks the hook fired and
	 * stores the payload; the caller resets the run and fires a resume pass.
	 */
	async consume(input: ConsumeWebhookInput): Promise<ConsumeResult> {
		const tokenHash = createHash("sha256").update(input.token).digest("hex");
		const hook = await this.scope().query.webhookHooks.findFirst({
			where: eq(webhookHooks.tokenHash, tokenHash),
		});
		if (!hook) {
			return { ok: false, reason: "not-found" };
		}
		if (hook.status !== "active") {
			return { ok: false, reason: "already-fired" };
		}
		if (hook.expiresAt.getTime() < Date.now()) {
			await this.scope()
				.update(webhookHooks)
				.set({ status: "expired" })
				.where(eq(webhookHooks.id, hook.id));
			return { ok: false, reason: "expired" };
		}
		await this.scope()
			.update(webhookHooks)
			.set({
				status: "fired",
				firedAt: new Date(),
				consumePayload: input.payload as never,
			})
			.where(eq(webhookHooks.id, hook.id));
		return {
			ok: true,
			hook: { ...hook, status: "fired" },
		};
	}
}

